import os
import subprocess

def count_lines(filename: str) -> int:
    try:
        process = subprocess.run(['wc', '-l', filename], check=True, universal_newlines=True, cwd=os.getcwd())
        return int(process.stdout)
    except FileNotFoundError:
        raise FileNotFoundError(f"File '{filename}' not found.")
    except subprocess.CalledProcessError as e:
        raise FileNotFoundError(f"Error while counting lines of file '{filename}': {e}")
```

